package com.ems.model; import jakarta.persistence.*; @Entity @Table(name="office_locations") public class OfficeLocation { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String name; private String address; private Double latitude; private Double longitude; private Double radiusMeters=150.0; private boolean active=true; public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public Double getLatitude(){return latitude;} public void setLatitude(Double v){latitude=v;} public Double getLongitude(){return longitude;} public void setLongitude(Double v){longitude=v;} public Double getRadiusMeters(){return radiusMeters;} public void setRadiusMeters(Double v){radiusMeters=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;} }
